<?php declare(strict_types=1); require __DIR__.'/../inc/service.php';
function h($s) { return htmlspecialchars((string)$s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); }
$available=true; try { $db=database(); $servers=live_servers($db); [$where,$args]=game_filter(); $q=$db->prepare('SELECT g.server_id,g.database_id,g.game_id,g.room_id,g.ended_at,g.ended_epoch,g.ranked,g.end_reason,g.player_count,g.winner_nick,s.name FROM directory_games g JOIN directory_servers s ON s.id=g.server_id WHERE '.$where.' ORDER BY g.ended_epoch DESC,g.ended_at DESC LIMIT 50'); $q->execute($args); $games=$q->fetchAll(); $count=(int)$db->query('SELECT COUNT(*) FROM directory_games')->fetchColumn(); $leaders=$db->query("SELECT s.name,g.winner_nick,COUNT(*) AS wins FROM directory_games g JOIN directory_servers s ON s.id=g.server_id WHERE g.ranked=1 AND g.end_reason='completed' AND g.winner_nick<>'' GROUP BY g.server_id,s.name,g.winner_nick ORDER BY wins DESC LIMIT 50")->fetchAll(); } catch(Throwable $e) { $available=false; http_response_code(503); }
?><!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>LineClash — Servers and statistics</title>
<style>body{background:#303446;color:#c6d0f5;font:17px system-ui;margin:2rem auto;padding:0 1rem;max-width:1100px}a{color:#8caaee}nav{display:flex;gap:2rem}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:1rem}article{background:#414559;padding:1.3rem;border-radius:12px}table{border-collapse:collapse;width:100%}td,th{padding:.6rem;text-align:left;border-bottom:1px solid #626880}.scroll{overflow:auto}small{color:#b5bfe2}</style>
<nav><a href="../">LineClash</a><a href="#servers">Servers</a><a href="#matches">Matches</a><a href="../api/?action=statistics">API</a></nav><h1>Servers &amp; statistics</h1>
<?php if(!$available): ?><p>The directory is temporarily unavailable.</p><?php else: ?>
<p><?=count($servers)?> live servers · <?=$count?> recorded games</p><small>Listings and results are reported by authenticated server operators. Nicknames are local to each server. New game times are UTC; legacy times retain the source server’s clock.</small>
<h2 id="servers">Server browser</h2><div class="grid"><?php foreach($servers as $s): ?><article><h3><?=h($s['name'])?></h3><p><code><?=h($s['host'])?>:<?=h($s['port'])?></code></p><p><?=h($s['status']['players']??'—')?> players · <?=h($s['status']['rooms']??'—')?> rooms</p><small>Announced <?=max(0,time()-(int)$s['last_seen'])?> seconds ago</small></article><?php endforeach; ?></div><?php if(!$servers): ?><p>No servers have announced recently.</p><?php endif; ?>
<h2 id="matches">Recent matches</h2><p><a href="?mode=all#matches">All</a> · <a href="?mode=ranked#matches">Ranked</a> · <a href="?mode=casual#matches">Casual</a></p><div class="scroll"><table><tr><th>Server</th><th>Ended</th><th>Mode</th><th>Room</th><th>Players</th><th>Winner</th></tr><?php foreach($games as $g): ?><tr><td><?=h($g['name'])?></td><td><?=h($g['ended_epoch']?gmdate('Y-m-d H:i:s',(int)$g['ended_epoch']).' UTC':$g['ended_at'].' (legacy)')?></td><td><?=h($g['ranked']?'Ranked':'Casual')?> / <?=h($g['end_reason'])?></td><td><?=h($g['room_id'])?></td><td><?=h($g['player_count'])?></td><td><a href="match.php?<?=h(http_build_query(['server'=>$g['server_id'],'database'=>$g['database_id'],'game'=>$g['game_id']]))?>"><?=h($g['winner_nick']?:'No winner')?> · Details / replay</a></td></tr><?php endforeach; ?></table></div><h2>Ranked wins</h2><small>Competitive completed rounds only. Names are scoped to each server; results are server-reported.</small><div class="scroll"><table><tr><th>Server</th><th>Player</th><th>Wins</th></tr><?php foreach($leaders as $l): ?><tr><td><?=h($l['name'])?></td><td><?=h($l['winner_nick'])?></td><td><?=h($l['wins'])?></td></tr><?php endforeach; ?></table></div><?php endif; ?></html>
